('11111111-1111-1111-1111-111111111111', 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'The Last Library', 'writing', 'A story about the last library on Earth after AI replaced all books.', 'en', 'open', 'published'),
('22222222-2222-2222-2222-222222222222', 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Midnight Seoul', 'screenplay', 'A noir thriller set in future Seoul where memories can be traded.', 'ko', 'open', 'published'),
