INSERT INTO branches (id, project_id, parent_branch_id, author_id, title, content, completion_percent, status) VALUES
('aaa11111-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', NULL, 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Chapter 1: The Keeper', '{"text": "<h2>Chapter 1: The Keeper</h2><p>Maya walked through the silent corridors of the Alexandria Project, the last physical library on Earth. Dust motes danced in the pale morning light.</p><p>She ran her fingers along the spines of books that no one came to read anymore. The government said physical books were inefficient. AI could summarize any book in seconds.</p><p>But Maya knew something they did not. There was magic in the turning of pages.</p>"}', 40, 'published'),
('aaa11111-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', 'aaa11111-0000-0000-0000-000000000001', 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Chapter 2: The Discovery', '{"text": "<h2>Chapter 2: The Discovery</h2><p>Hidden behind a false wall in the basement, Maya found thousands of handwritten manuscripts that had never been digitized.</p><p>She opened the first journal: <em>If you are reading this, the library still stands.</em></p>"}', 25, 'published'),
('aaa11111-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'aaa11111-0000-0000-0000-000000000001', 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Alt: The Rebellion', '{"text": "<h2>The Rebellion</h2><p>Maya did not just want to preserve the books. She wanted to fight back. She began organizing secret reading circles in the basement every Tuesday night.</p>"}', 15, 'published'),
('aaa11111-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', 'aaa11111-0000-0000-0000-000000000002', 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Chapter 3: The Author', '{"text": "<h2>Chapter 3: The Author</h2><p>The journal entries led Maya to a name: Elias Park. A writer who had predicted the fall of libraries thirty years ago.</p>"}', 10, 'published');
INSERT INTO branches (id, project_id, parent_branch_id, author_id, title, content, completion_percent, status) VALUES
('bbb22222-0000-0000-0000-000000000001', '22222222-2222-2222-2222-222222222222', NULL, 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee', 'Scene 1: The Memory Market', '{"text": "<h2>INT. MEMORY MARKET - NIGHT</h2><p>Neon signs flicker in Hangul and English. JOON (30s, weary eyes) navigates through narrow alleys lined with memory vendors.</p><p>VENDOR: Fresh memories today. A summer in Jeju. First love. Graduation day.</p><p>Joon ignores them all. He is looking for something specific.</p>"}', 30, 'published');
